  // Check if the user has permission to ban
  if (!interaction.member.permissions.has(PermissionsBitField.Flags.BanMembers)) {
    return interaction.reply({ content: 'You do not have permission to ban members.', ephemeral: true });
  }

  // Get the member to ban
  const member = interaction.guild.members.cache.get(interaction.options.getMember('member').id);

  // Check if the member exists
  if (!member) {
    return interaction.reply({ content: 'Member not found.', ephemeral: true });
  }

  // Ban the member
  try {
    await member.ban({ reason: 'Banned by the bot.' });
    return interaction.reply({ content: `Successfully banned ${member.user.tag}.`, ephemeral: true });
  } catch (error) {
    return interaction.reply({ content: `Failed to ban ${member.user.tag}. Error: ${error}`, ephemeral: true });
  }
}
```

6. Create a function to register the ban command:
```javascript
function registerCommands() {
  // Create the ban command
  const banCommand = new SlashCommandBuilder()
    .setName('ban')
    .setDescription('Bans a member from the server.')
    .addUserOption(option => option.setName('member').setDescription('The member to ban').setRequired(true));

  // Register the command
  client.application.commands.create(banCommand);
}
```

