  console.log('Ready!');
  registerCommands();
});

client.login('YOUR_DISCORD_BOT_TOKEN');
```

8. Replace `YOUR_DISCORD_BOT_TOKEN` with your actual Discord bot token.

9. Run the bot by executing `node discord-bot.js` in your terminal.

