  for (let i = 0; i < arr.length; i++) {
    let num = arr[i];
    if (num > 1) {
      for (let j = 2; j < num; j++) {
        if (num % j === 0) {
          break; // Number is not prime, so move to next number in the array
        }
      }
      if (j === num) {
        console.log(`The prime number is ${num}`);
        return; // Found a prime number, so stop checking further numbers
      }
    }
  }
  console.log("No prime numbers found in the given array.");
}

// Example usage:
